tests.code:
// Doctor should see a patient selector dropdown
const selectorVisible = await analysisPage.isDisplayed(analysisPage.locators.patientSelector);
expect(selectorVisible).to.be.true;

// By default no patient is selected, locked overlay shown
const lockedVisible = await analysisPage.isLockedOverlayVisible();
expect(lockedVisible).to.be.true;

const options = await analysisPage.getPatientOptions();
// At least the default "Choose a patient" option should exist
expect(options.length).to.be.at.least(1);

if (!isLoggedIn) { this.skip(); return; }
await analysisPage.open();
// Select the first non-default patient if available
try {
  const options = await analysisPage.getPatientOptions();
  if (options.length > 1) {
    const patientId = await options[1].getAttribute('value');
    if (patientId) {
      await driver.executeScript(`
        const sel = document.querySelector('.patient-selector select');
        if (sel) {
          sel.value = arguments[0];
          sel.dispatchEvent(new Event('change', { bubbles: true }));
        }
      `, patientId);
      await WaitHelpers.sleep(1000);
      const uploadVisible = await analysisPage.isUploadZoneVisible();
      expect(uploadVisible).to.be.true;
    } else {
      this.skip();
    }
  } else {
    logger.info('No patients registered - skipping upload zone test.');
    this.skip();
  }
} catch (e) {
  logger.warn(`Upload zone test skipped: ${e.message}`);
  this.skip();
}

